export class ModelRuntime {
  static async create() { return new ModelRuntime(); }
  getProvider(id) { return id === 'fixture-provider' ? { id, name: id, auth: { apiKey: true } } : null; }
  getModel(provider, model) { return provider === 'fixture-provider' && model === 'fixture-model' ? { id: model } : null; }
  getProviders() { return [this.getProvider('fixture-provider')]; }
  async refresh() {}
  async login() {}
}
